"use client";

/**
 * AdStrip — franja de publicidad de Subastop entre las dos tiendas (vmc-index-lab, AdStrip).
 * Ocupa el lugar del «BANNER · 766 × 100» del Homepage. Pieza «Venta para empresas · 03 Tecnología» en HTML propio
 * (public/index/banners/venta-empresa.html, con el sistema de subastop.com): franja 1532 × 200 en escritorio y 776 × 232
 * en celular. El iframe se dibuja a su tamaño de diseño y se escala al ancho disponible, como una imagen.
 */
import { useEffect, useRef, useState } from "react";
import type { JSX } from "react";

export default function AdStrip(): JSX.Element {
  const ref = useRef<HTMLElement>(null);
  const [w, setW] = useState(0);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const ro = new ResizeObserver(([e]) => setW(e.contentRect.width));
    ro.observe(el);
    return () => ro.disconnect();
  }, []);
  const f = w > 0 && w < 600 ? { id: "strip776", w: 776, h: 232 } : { id: "strip1532", w: 1532, h: 200 };
  return (
    <aside ref={ref} aria-label="Publicidad" style={{ position: "relative", display: "block", width: "100%", overflow: "hidden", borderRadius: 16,
      boxShadow: "rgba(0,0,0,0.07) 0px 0px 16px 4px", aspectRatio: `${f.w} / ${f.h}` }}>
      {w ? <iframe key={f.id} src={`/index/banners/venta-empresa.html?v=03-tecnologia&f=${f.id}`} title="Venta para empresas: ¿Renovaste tecnología? Vende la anterior."
        width={f.w} height={f.h} loading="lazy" style={{ position: "absolute", top: 0, left: 0, display: "block", border: 0, transformOrigin: "0 0", transform: `scale(${w / f.w})` }} /> : null}
    </aside>
  );
}

/**
 * CampaignBanner — banner secundario del Index (vmc-index-lab, CampaignBanner, vista «Foto de fondo»).
 * Reemplaza el hueco «SECONDARY BANNER» del Homepage. Mismo lenguaje que el banner principal: degradado del sistema,
 * foto a la derecha fundida con máscara y el mensaje en un panel de vidrio. Campaña por defecto: Valoriza tu auto.
 */
import type { JSX } from "react";
import GlassButton from "@/concorde/components/GlassButton";

const SHADOW = "rgba(0,0,0,0.07) 0px 0px 16px 4px";

export type Campaign = { eyebrow: string; title: JSX.Element; aria: string; lead: string; cta: string; image: string; position: string; bg: string; href?: string };

export const VALORIZA: Campaign = {
  eyebrow: "Valoriza en VMC", aria: "Cuánto vale tu auto", title: <>¿Cuánto <em>vale</em> tu auto?</>,
  lead: "Responde unas preguntas y conoce el valor estimado de tu auto.", cta: "Valoriza tu auto",
  image: "/index/banners/vmc/campana-valor.jpg", position: "65% 25%", bg: "linear-gradient(100deg, #2A1670 0%, #3D2299 45%, #403566 100%)",
};

const CAMPAIGN_CSS = String.raw`
.hib-campaign { position: relative; box-sizing: border-box; display: block; width: 100%; height: 204px; overflow: hidden; border-radius: 16px; color: #fff;
  box-shadow: ${SHADOW}; font-family: var(--vmc-font-display, 'Plus Jakarta Sans', sans-serif); }
.hib-campaign__media { position: absolute; top: 0; right: 0; bottom: 0; width: 68%; overflow: hidden;
  -webkit-mask-image: linear-gradient(90deg, transparent 0%, #000 34%); mask-image: linear-gradient(90deg, transparent 0%, #000 34%); }
.hib-campaign__media img { display: block; width: 100%; height: 100%; object-fit: cover; transition: transform 600ms cubic-bezier(0.2,0,0,1); }
.hib-campaign:hover .hib-campaign__media img { transform: scale(1.04); }
.hib-campaign__copy { position: absolute; z-index: 1; left: 20px; top: 50%; transform: translateY(-50%); box-sizing: border-box; width: min(440px, 52%);
  display: grid; justify-items: start; gap: 6px; padding: 16px 20px 18px; border-radius: 16px; background: rgba(255,255,255,0.1); border: 1px solid rgba(255,255,255,0.22);
  -webkit-backdrop-filter: blur(16px) saturate(140%); backdrop-filter: blur(16px) saturate(140%);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.25), 0 10px 30px rgba(20,8,60,0.3); }
.hib-campaign__eyebrow { display: inline-flex; align-items: center; gap: 6px; padding: 3px 10px 3px 8px; border-radius: 999px; background: rgba(255,255,255,0.14);
  font-size: 11px; font-weight: 600; color: #fff; }
.hib-campaign__eyebrow::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: #FFD7B0; box-shadow: 0 0 0 3px rgba(255,215,176,0.3); }
.hib-campaign h2 { margin: 0; font-size: 22px; line-height: 26px; font-weight: 800; letter-spacing: -0.02em; color: #fff; text-wrap: balance; }
.hib-campaign h2 em { font-style: normal; color: #FFD7B0; }
.hib-campaign p { margin: 0 0 6px; font-size: 12px; line-height: 16px; color: rgba(255,255,255,0.85); }
@media (max-width: 1023px) {
  .hib-campaign { height: auto; min-height: 340px; display: flex; align-items: flex-end; padding: 12px; }
  .hib-campaign__media { width: 100%; height: 62%; bottom: auto; -webkit-mask-image: linear-gradient(180deg, #000 55%, transparent 100%); mask-image: linear-gradient(180deg, #000 55%, transparent 100%); }
  .hib-campaign__copy { position: relative; left: auto; top: auto; transform: none; width: 100%; }
}
@media (prefers-reduced-motion: reduce) { .hib-campaign__media img { transition: none; } }
`;

export default function CampaignBanner({ campaign = VALORIZA }: { campaign?: Campaign }): JSX.Element {
  const c = campaign;
  return (
    <section className="hib-campaign" aria-label={c.aria} style={{ background: c.bg }}>
      <style href="concorde-index-campaign" precedence="default">{CAMPAIGN_CSS}</style>
      <div className="hib-campaign__copy">
        <small className="hib-campaign__eyebrow">{c.eyebrow}</small>
        <h2>{c.title}</h2>
        <p>{c.lead}</p>
        {c.href ? <GlassButton href={c.href}>{c.cta}</GlassButton> : <GlassButton>{c.cta}</GlassButton>}
      </div>
      <div className="hib-campaign__media"><img src={c.image} alt="" style={{ objectPosition: c.position }} /></div>
    </section>
  );
}

/**
 * CategoryRail — «Explora por categoría» del Index (vmc-index-lab, CategoryRail, vista «Normal» · «Fila de 6»).
 * Evolución de la columna «CATEGORÍAS» del CategoriesSection del Homepage: pasa de 4 CategoryCard con ícono a
 * 6 cards con foto, ícono de vidrio (Vidrio) y conteo de lotes. En celular, 2 columnas.
 */
import type { JSX } from "react";
import { Vidrio } from "@/concorde/components/Vidrio";
import { CATEGORIES } from "../shared/data";
import SectionHead from "./SectionHead";

const CATEGORY_CSS = String.raw`
.hib-cats { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 10px; margin: 0; padding: 0 0 6px; list-style: none; }
.hib-cats > li { display: flex; min-width: 0; }
.hib-cat { flex: 1; display: flex; flex-direction: column; overflow: hidden; border-radius: 8px; background: #fff; color: inherit; text-decoration: none;
  box-shadow: rgba(0,0,0,0.07) 0 0 16px 4px; transition: transform 150ms cubic-bezier(0.3,0,0,1), box-shadow 150ms cubic-bezier(0.3,0,0,1); }
.hib-cat:hover { transform: translateY(-3px); box-shadow: oklch(0.22 0.18 285 / 0.12) 0 12px 20px; }
.hib-cat:focus-visible { outline: 2px solid #8460e5; outline-offset: 2px; }
.hib-cat > img { display: block; width: 100%; height: 92px; object-fit: cover; }
.hib-cat__foot { flex: 1; display: grid; grid-template-columns: 32px minmax(0,1fr) 20px; gap: 6px; align-items: center; padding: 8px 6px 8px 8px; }
.hib-cat__icon { display: grid; place-items: center; width: 32px; height: 32px; }
.hib-cat__txt { display: grid; min-width: 0; }
.hib-cat__txt b { font-size: 12px; line-height: 1.2; color: #3b1782; }
.hib-cat__txt small { font-size: 11px; color: #5b5b66; }
.hib-cat__go { display: grid; place-items: center; width: 20px; height: 20px; border-radius: 50%; color: #3b1782; background: #F3EFFD; }
@media (max-width: 1023px) { .hib-cats { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (prefers-reduced-motion: reduce) { .hib-cat { transition: none; } }
`;

export default function CategoryRail(): JSX.Element {
  return (
    <section aria-label="Explora por categoría" style={{ boxSizing: "border-box", width: "100%", fontFamily: "var(--vmc-font-display, 'Plus Jakarta Sans', sans-serif)" }}>
      <style href="concorde-index-categories" precedence="default">{CATEGORY_CSS}</style>
      <SectionHead title="Explora por categoría" subtitle="Encuentra oportunidades por tipo de activo" action="Ver todas las categorías" />
      <ul className="hib-cats">
        {CATEGORIES.map(({ label, count, icon, image }) => (
          <li key={label}>
            <a href="#" className="hib-cat vd-host" aria-label={`${label} · ${count}`}>
              <img src={image} alt="" />
              <span className="hib-cat__foot">
                <span className="hib-cat__icon"><Vidrio s={icon} size={32} /></span>
                <span className="hib-cat__txt"><b>{label}</b><small>{count}</small></span>
                <span className="hib-cat__go" aria-hidden><svg width="12" height="12" viewBox="0 0 20 20"><path d="M4 10h11M11 5l5 5-5 5" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" /></svg></span>
              </span>
            </a>
          </li>
        ))}
      </ul>
    </section>
  );
}

/**
 * CompaniesMarquee — «Empresas que publican en VMC» del Index: cabecera de sección + LogoMarquee. Sección nueva.
 */
import type { JSX } from "react";
import LogoMarquee from "@/concorde/components/LogoMarquee";
import { COMPANIES } from "../shared/data";
import SectionHead from "./SectionHead";

export default function CompaniesMarquee(): JSX.Element {
  return (
    <section aria-label="Empresas que publican en VMC" style={{ boxSizing: "border-box", width: "100%", fontFamily: "var(--vmc-font-display, 'Plus Jakarta Sans', sans-serif)" }}>
      <SectionHead title="Empresas que publican en VMC" subtitle="Tiendas especializadas que publican en VMC" />
      <LogoMarquee ariaLabel="Empresas que publican en VMC"
        items={COMPANIES.map((c) => ({ name: c.name, logo: c.logo, caption: c.lots, href: "#" }))} />
    </section>
  );
}

// Index (escritorio). Lienzo de 1024 como el del lab (vmc-index-lab, HomeIndexRebase.module.css):
// el sidebar cerrado (76) deja 948 de contenido; abierto (226) deja 798, el ancho del Homepage.
// El alto lo da el contenido (es fluido); INDEX_HEIGHT es el medido con el sidebar cerrado y sirve
// para la miniatura del catálogo /blocks. El visor mide el alto real en vivo.
export const INDEX_SHELL_WIDTH = 1024;
export const INDEX_WIDTH = 948;
export const INDEX_HEIGHT = 2620;

"use client";

/**
 * Index — Bloque de Concorde (Voyager DS). Evolución del bloque Homepage: el nuevo inicio de VMC.
 * Origen: vmc-index-lab (apps/index-lab/app/qa/home-index-rebase), vista por defecto «Opción A», sin los controles de QA.
 *
 * Orden (escritorio):
 *   1. Banner principal (IndexHero: HeroCarousel) a la izquierda y VMC ahora (feed en vivo) a la derecha, a dos filas de alto.
 *   2. Tipo de oferta (OfferTypeCards) bajo el banner.
 *   3. Tienda Autoplan (StoreLots: FeaturedCard + LotGallery) · franja de publicidad (AdStrip) · tienda Mapfre.
 *   4. Explora por categoría (CategoryRail) · banner de campaña (CampaignBanner) · Vende tu vehículo (SellSection)
 *      · Empresas que publican en VMC (CompaniesMarquee: LogoMarquee).
 * En celular (< 1024 px de pantalla) todo va en una columna: banner, VMC ahora, tiendas, Tipo de oferta y el resto.
 * Contenido de ejemplo; sin inventario real.
 */
import type { JSX } from "react";
import OfferTypeCards from "@/concorde/components/OfferTypeCards";
import VmcAhora from "@/concorde/components/VmcAhora";
import { OFFER_TYPES, STORES } from "../shared/data";
import AdStrip from "./AdStrip";
import CampaignBanner from "./CampaignBanner";
import CategoryRail from "./CategoryRail";
import CompaniesMarquee from "./CompaniesMarquee";
import IndexHero from "./IndexHero";
import SectionHead from "./SectionHead";
import SellSection from "./SellSection";
import StoreLots from "./StoreLots";
export { INDEX_WIDTH, INDEX_HEIGHT, INDEX_SHELL_WIDTH } from "./dimensions";

const GAP = 16;
const HERO_H = 300;

// La fuente (Plus Jakarta Sans de 500 a 800) la pone la página que monta el bloque.
const INDEX_CSS = String.raw`
.hib-home { font-family: var(--vmc-font-display, 'Plus Jakarta Sans', -apple-system, sans-serif); }
.hib-ot-mobile { display: none; width: 100%; }
@media (max-width: 1023px) {
  .hib-home { overflow-x: clip; padding: 14px !important; gap: 18px !important; }
  /* Celular: banner y justo después VMC ahora; Tipo de oferta baja, después de las tiendas. */
  .hib-top-grid { grid-template-columns: minmax(0, 1fr) !important; grid-template-rows: ${HERO_H}px 390px !important; gap: 14px !important; }
  .hib-top-grid > [data-slot="principal-banner"] { grid-column: 1 !important; grid-row: 1 !important; }
  .hib-top-grid > [data-slot="secondary-banner"] { grid-column: 1 !important; grid-row: 2 !important; height: 390px !important; }
  .hib-top-grid > [data-slot="offer-type"] { display: none; }
  .hib-ot-mobile { display: block; }
  /* «Ver más»: VMC ahora crece con su contenido (sin el alto fijo de 390 ni scroll interno). */
  .hib-top-grid[data-feedmore] { grid-template-rows: ${HERO_H}px auto !important; }
  .hib-top-grid[data-feedmore] > [data-slot="secondary-banner"] { height: auto !important; }
  .hib-section-head { align-items: flex-start !important; flex-wrap: wrap; gap: 10px !important; }
  .hib-section-head__title { white-space: normal !important; }
}
@media (max-width: 480px) { .hib-home { padding: 12px !important; } }
`;

function OfferType(): JSX.Element {
  return (
    <section aria-label="Tipo de oferta" style={{ boxSizing: "border-box", width: "100%" }}>
      <SectionHead title="Tipo de oferta" subtitle="Elige cómo quieres comprar" />
      <OfferTypeCards items={OFFER_TYPES} />
    </section>
  );
}

export interface IndexProps {
  /** Celular «Opción A»: VMC ahora como tarjeta con «Ver más» que crece con su contenido (sin scroll interno). */
  feedMore?: boolean;
  className?: string;
}

export default function Index({ feedMore = false, className = "" }: IndexProps): JSX.Element {
  return (
    <div data-block="index" className={`hib-home${className ? ` ${className}` : ""}`}
      style={{ width: "100%", padding: 16, boxSizing: "border-box", background: "#ffffff", display: "flex", flexDirection: "column", alignItems: "center", gap: GAP }}>
      <style href="concorde-index" precedence="default">{INDEX_CSS}</style>
      <div className="hib-top-grid" data-feedmore={feedMore || undefined}
        style={{ position: "relative", width: "100%", display: "grid", gridTemplateColumns: "minmax(0, 1fr) minmax(300px, 32%)", gridTemplateRows: `${HERO_H}px auto`, gap: GAP }}>
        <div data-slot="principal-banner" style={{ gridColumn: 1, gridRow: 1, minWidth: 0, display: "flex", height: "100%" }}><IndexHero /></div>
        <div data-slot="secondary-banner" style={{ gridColumn: 2, gridRow: "1 / 3", minWidth: 0, minHeight: 0, display: "flex", height: "100%", position: "relative" }}>
          {/* El feed no empuja la fila: se dibuja absoluto y toma el alto que dejan banner + Tipo de oferta. */}
          {feedMore
            ? <div style={{ display: "flex", width: "100%" }}><VmcAhora view="timeline" more /></div>
            : <div style={{ position: "absolute", inset: 0, display: "flex" }}><VmcAhora view="timeline" /></div>}
        </div>
        <div data-slot="offer-type" style={{ gridColumn: 1, gridRow: 2, minWidth: 0 }}><OfferType /></div>
      </div>
      <StoreLots store={STORES[0]} />
      <AdStrip />
      <StoreLots store={STORES[1]} />
      <div className="hib-ot-mobile"><OfferType /></div>
      <CategoryRail />
      <CampaignBanner />
      <SellSection />
      <CompaniesMarquee />
    </div>
  );
}

"use client";

/**
 * IndexHero — banner principal del Index: las 3 campañas de VMC en un HeroCarousel.
 * Reemplaza el hueco «PRINCIPAL BANNER» del Homepage. Copy provisional (lo ajusta Julio).
 * Es componente cliente a propósito: HeroCarousel recorre el JSX del título para animarlo letra por letra,
 * y ese JSX tiene que crearse en el cliente (si llega serializado desde un Server Component, no hidrata igual).
 */
import type { JSX } from "react";
import HeroCarousel, { type HeroSlide } from "@/concorde/components/HeroCarousel";

export const INDEX_SLIDES: HeroSlide[] = [
  { label: "Entérate primero de las subastas por WhatsApp", pill: { tone: "whatsapp", text: "Canal de WhatsApp" },
    title: <>Entérate <em>primero</em><br />de las subastas</>, lead: <>Únete al canal de VMC y recibe los lotes<br />nuevos antes que nadie.</>,
    cta: "Unirme al canal", bg: "linear-gradient(100deg, #2A1670 0%, #3D2299 34%, #0E7A5A 78%, #25D366 100%)",
    photo: { src: ["/index/banners/vmc/hero-whatsapp-c.jpg", "/index/banners/vmc/hero-whatsapp.jpg"], side: "r", position: "70% 30%", alto: true }, copy: "left" },
  { label: "Publica tu auto en VMC y recibe ofertas", pill: { tone: "seller", text: "Publica en VMC" },
    title: <>Publica tu auto<br />y <em>recibe ofertas</em></>, lead: <>Recibe propuestas y elige la que más te convenga.</>,
    cta: "Publicar mi auto", bg: "linear-gradient(100deg, #2A1670 0%, #3D2299 34%, #6B48DD 76%, #8460E5 100%)",
    photo: { src: ["/index/banners/vmc/hero-publica.jpg"], side: "l", position: "30% 30%" }, copy: "right" },
  { label: "Tú pones el precio y el 100% es tuyo", pill: { tone: "negotiable", text: "Recibe ofertas" },
    title: <>¡Tú pones el precio<br />y <em>el 100% es tuyo</em>!</>, lead: <>Publica tu auto en minutos y negocia directo con los compradores.</>,
    cta: "¡Publica ahora!", bg: "linear-gradient(100deg, #2A1670 0%, #3D2299 35%, #00838C 78%, #00D2D3 100%)",
    photo: { src: ["/index/banners/vmc/hero-negociable-a.jpg"], side: "r", position: "70% 20%", alto: true }, copy: "left" },
];

/** `pick`: índices de las diapositivas a mostrar (por defecto, las 3). */
export default function IndexHero({ pick }: { pick?: number[] }): JSX.Element {
  return <HeroCarousel slides={pick ? pick.map((i) => INDEX_SLIDES[i]) : INDEX_SLIDES} />;
}

/**
 * SectionHead — cabecera de las secciones planas del Index (título, bajada, filete y acción opcional).
 * La acción es el ProfileButton de Concorde (el mismo «Ir al Perfil» del Homepage).
 */
import type { JSX } from "react";
import ProfileButton from "@/concorde/components/ProfileButton";

export default function SectionHead({ title, subtitle, action }: { title: string; subtitle: string; action?: string }): JSX.Element {
  return (
    <header className="hib-section-head" style={{ boxSizing: "border-box", flex: "none", display: "flex", alignItems: "flex-end", justifyContent: "space-between", gap: 16, padding: "0 0 10px", marginBottom: 14, borderBottom: "1px solid #DEDCE4" }}>
      <div style={{ display: "grid", gap: 2, minWidth: 0 }}>
        <h2 className="hib-section-head__title" style={{ margin: 0, fontSize: 16, lineHeight: "20px", fontWeight: 700, letterSpacing: "-0.01em", color: "#3b1782", whiteSpace: "nowrap" }}>{title}</h2>
        <p style={{ margin: 0, fontSize: 12, lineHeight: "16.8px", color: "#6B6878" }}>{subtitle}</p>
      </div>
      {action ? <div style={{ flex: "none" }}><ProfileButton>{action}</ProfileButton></div> : null}
    </header>
  );
}

/**
 * SellSection — «Vende tu vehículo» del Index (vmc-index-lab, SellSection). Sección nueva: no existía en el Homepage.
 * Dos opciones a la izquierda (ProfileButton de Concorde) y el beneficio de SubasCars a la derecha (GlassButton).
 */
import type { JSX } from "react";
import GlassButton from "@/concorde/components/GlassButton";
import ProfileButton from "@/concorde/components/ProfileButton";
import SectionHead from "./SectionHead";

const SELL_CSS = String.raw`
.hib-sell { box-sizing: border-box; width: 100%; color: #191C1C; font-family: var(--vmc-font-display, "Plus Jakarta Sans", sans-serif); }
.hib-sell *, .hib-sell *::before, .hib-sell *::after { box-sizing: border-box; }
.hib-sell__layout { display: grid; grid-template-columns: minmax(0, 1fr) clamp(260px, 34%, 300px); gap: 16px; align-items: stretch; }
.hib-sell__choices { display: grid; gap: 12px; }
.hib-sell__choice { display: grid; grid-template-columns: 132px minmax(0, 1fr); min-height: 142px; overflow: hidden; border: 1px solid #DEDCE4; border-radius: 14px; background: #fff; text-decoration: none; color: inherit; transition: transform .2s ease, box-shadow .2s ease, border-color .2s ease; }
.hib-sell__choice:hover { transform: translateY(-2px); border-color: #B7A5E9; box-shadow: rgb(32 0 104 / 14%) 0 12px 24px -16px; }
.hib-sell__photo { position: relative; overflow: hidden; background: #E8E5FF; }
.hib-sell__photo img { display: block; width: 100%; height: 100%; object-fit: cover; }
.hib-sell__photo::after { content: ""; position: absolute; inset: 0; background: linear-gradient(90deg, transparent 56%, rgb(255 255 255 / 92%) 100%); pointer-events: none; }
.hib-sell__copy { display: flex; flex-direction: column; justify-content: center; align-items: flex-start; min-width: 0; padding: 14px 16px; }
.hib-sell__copy h3 { margin: 0; color: #191C1C; font-size: 14px; line-height: 18px; font-weight: 700; letter-spacing: -.01em; }
.hib-sell__copy p { margin: 4px 0 10px; color: #6B6878; font-size: 12px; line-height: 16.8px; }
.hib-sell__copy .pprofilebtn { padding: 0; }
.hib-sell__benefit { position: relative; isolation: isolate; display: flex; flex-direction: column; align-items: flex-start; min-height: 296px; overflow: hidden; padding: 22px; border-radius: 14px; color: #fff;
  background: radial-gradient(110% 100% at -10% 112%, rgb(239 133 46 / 88%) 0%, rgb(239 133 46 / 38%) 27%, transparent 56%), linear-gradient(145deg, #32136F 0%, #4E22A9 55%, #7B4BE3 100%); box-shadow: rgb(59 23 130 / 18%) 0 12px 24px -18px; }
.hib-sell__benefit::before { content: ""; position: absolute; z-index: -1; top: -85px; right: -48px; width: 250px; height: 210px; border: 42px solid rgb(255 255 255 / 10%); border-radius: 50%; }
.hib-sell__benefit::after { content: ""; position: absolute; z-index: -1; right: -74px; bottom: -118px; width: 270px; height: 210px; border: 42px solid rgb(255 255 255 / 8%); border-radius: 50%; }
.hib-sell__person { position: absolute; z-index: 0; right: -26px; bottom: -1px; width: min(68%, 238px); height: auto; pointer-events: none; }
.hib-sell__benefit > :not(.hib-sell__person) { position: relative; z-index: 1; }
