            y una línea gris con autor · tiempo · participantes o negociaciones. */}
        {items.map((e, i) => {
          const t = toned(describe(e, s.inv, (s.now - e.at) / 60_000), s.design);
          const o = s.inv.find((x) => x.id === e.offerId);
          return (
            <li key={e.uid} className={`va-item${enter(i)}`}>
