              <div className="va-item__main">
                {s.design.tags === "con" ? <span className="va-item__pill" style={{ "--k": t.color } as CSSProperties}>{t.pill}</span> : null}
                <p className="va-item__title">{t.mode && o ? o.lot : t.title}</p>
